CREATE TYPE "PerformanceCycleStatus" AS ENUM ('DRAFT','ACTIVE','REVIEW','CLOSED');
CREATE TYPE "PerformanceReviewStatus" AS ENUM ('DRAFT','SUBMITTED','MANAGER_REVIEWED','HR_REVIEWED','ACKNOWLEDGED');
CREATE TABLE "PerformanceCycle" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"name" TEXT NOT NULL,"startsAt" DATE NOT NULL,"endsAt" DATE NOT NULL,"status" "PerformanceCycleStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PerformanceCycle_pkey" PRIMARY KEY("id"));
CREATE TABLE "PerformanceReview" ("id" TEXT NOT NULL,"companyId" TEXT NOT NULL,"cycleId" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"reviewerId" TEXT NOT NULL,"status" "PerformanceReviewStatus" NOT NULL DEFAULT 'DRAFT',"overallRating" DOUBLE PRECISION,"goalRating" DOUBLE PRECISION,"competencyRating" DOUBLE PRECISION,"strengths" TEXT,"growthAreas" TEXT,"summary" TEXT,"submittedAt" TIMESTAMP(3),"reviewedAt" TIMESTAMP(3),"acknowledgedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PerformanceReview_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "PerformanceCycle_companyId_name_key" ON "PerformanceCycle"("companyId","name");CREATE INDEX "PerformanceCycle_companyId_status_idx" ON "PerformanceCycle"("companyId","status");CREATE UNIQUE INDEX "PerformanceReview_cycleId_employeeId_key" ON "PerformanceReview"("cycleId","employeeId");CREATE INDEX "PerformanceReview_companyId_status_idx" ON "PerformanceReview"("companyId","status");CREATE INDEX "PerformanceReview_reviewerId_status_idx" ON "PerformanceReview"("reviewerId","status");
ALTER TABLE "PerformanceCycle" ADD CONSTRAINT "PerformanceCycle_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PerformanceReview" ADD CONSTRAINT "PerformanceReview_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PerformanceReview" ADD CONSTRAINT "PerformanceReview_cycleId_fkey" FOREIGN KEY("cycleId") REFERENCES "PerformanceCycle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PerformanceReview" ADD CONSTRAINT "PerformanceReview_employeeId_fkey" FOREIGN KEY("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PerformanceReview" ADD CONSTRAINT "PerformanceReview_reviewerId_fkey" FOREIGN KEY("reviewerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
